algorithms.pseudocode:
def score(m):
    return max(m.lag_s / LAG_RED, m.buffer_occ / 0.9,
               m.sink_p99 / P99_RED, m.kafka_disk / 0.85)

LEVELS = [(0.5,'green'),(0.7,'yellow'),(0.9,'orange'),(inf,'red')]
MULT = {'green':  {'critical':1,'standard':1,  'bulk':1},
        'yellow': {'critical':1,'standard':1,  'bulk':0.5},
        'orange': {'critical':1,'standard':0.7,'bulk':0.1},
        'red':    {'critical':1,'standard':0.4,'bulk':0}}   # bulk spilled

def tick(m):
    target = first(l for t,l in LEVELS if score(m) < t)
    if rank(target) > rank(current): current = target; since = now()
    elif rank(target) < rank(current) and now()-since > 120s:
        current = step_down(current); since = now()
    publish(current, MULT[current])
